from collections import OrderedDict

def solve(operations, capacity):
    cache = OrderedDict()
    results = []
    for op in operations:
        action = op[0]
        key = op[1]
        if action == 'PUT':
            val = op[2]
            if key in cache:
                cache.move_to_end(key)
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = val
        elif action == 'GET':
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)
    return results
